---@class UIMazeSmallMapNode
---@field noGetTo                       	UnityEngine.RectTransform               
---@field noPass                        	UnityEngine.RectTransform               
---@field pass                          	UnityEngine.RectTransform               
---@field isPass                        	UnityEngine.RectTransform               
---@field isCurPos                      	UnityEngine.RectTransform               
---@field icon                          	UnityEngine.RectTransform               
---@field isNextPoint                   	UnityEngine.RectTransform                                       
local UIMazeSmallMapNode = Class("UIMazeSmallMapNode")
function UIMazeSmallMapNode:__init() 
    self._data = nil
end

function UIMazeSmallMapNode:__delete()
    self._data = nil
end

function UIMazeSmallMapNode:Awake()
end

function UIMazeSmallMapNode:Start()
end

function UIMazeSmallMapNode:Refresh(data)
    if not data then
        return
    end
    self._data = data
    self:FillMiniMapPoint()
end

function UIMazeSmallMapNode:FillMiniMapPoint()
    local curPoint = MazeMapMgr:GetInstance().curPoint
    CfUtils.FillImage(self.icon, CfUtils.GetMazeMiniMapPoint(self._data.type), true)

    if checkNumber(self._data.line) <= checkNumber(curPoint.line) then
        local isPassPoint = MazeMgr:GetInstance():IsPassCurPoint(self._data)
        if checkNumber(self._data.line) == checkNumber(curPoint.line) then
            if MazeMapMgr:GetInstance():IsCurPoint(self._data) then
                KTool.SetActive(self.isPass,true)
                KTool.SetActive(self.noGetTo,false)

                if isPassPoint then
                    KTool.SetActive(self.pass, checkNumber(self._data.passType) == 1)
                    KTool.SetActive(self.noPass, checkNumber(self._data.passType) == 2)
                else
                    KTool.SetActive(self.noPass, false)
                    KTool.SetActive(self.pass, false)
                end
            else
                KTool.SetActive(self.isPass,false)
                KTool.SetActive(self.noGetTo,true)
            end
        elseif self._data.line < curPoint.line then
            --该点在历史足迹中
            if isPassPoint then
                KTool.SetActive(self.isPass,true)
                KTool.SetActive(self.noGetTo,false)

                KTool.SetActive(self.pass, checkNumber(self._data.passType) == 1)
                KTool.SetActive(self.noPass, checkNumber(self._data.passType) == 2)
            else
                KTool.SetActive(self.isPass,false)
                KTool.SetActive(self.noGetTo,true)
            end
        end        
    else
        KTool.SetActive(self.noGetTo, false)
        KTool.SetActive(self.isPass, false)
    end
    
    --如果是下一关的点
    if MazeMapMgr:GetInstance():IsNextPoints(self._data) then
        --如果通关了当前的点 采取绘制下一关的点
        if MazeMgr:GetInstance():IsPassCurPoint() then
            KTool.SetActive(self.isNextPoint, MazeMapMgr:GetInstance():IsCanArrivePoint(self._data))

            KTool.SetActive(self.isPass, false)
            KTool.SetActive(self.noGetTo, not MazeMapMgr:GetInstance():IsCanArrivePoint(self._data))
        end
    else
        KTool.SetActive(self.isNextPoint, false)
    end

    KTool.SetActive(self.isCurPos, MazeMapMgr:GetInstance():IsCurPoint(self._data))
end

function UIMazeSmallMapNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIMazeSmallMapNode
